begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,created_at,updated_at) values
('00000000-0000-0000-0000-000000000000','f3111111-1111-4111-8111-111111111111','authenticated','authenticated','finance-owner@example.test','',now(),now()),
('00000000-0000-0000-0000-000000000000','f3222222-2222-4222-8222-222222222222','authenticated','authenticated','finance-other@example.test','',now(),now());
select set_config('finance.test.draft','{"asOf": "2026-09-21", "currency": "GBP", "coverage": {"from": "2025-09-01", "to": "2026-09-21", "completeThrough": "2026-08", "transactionCount": 20, "accountCount": 2, "note": "Synthetic data"}, "accounts": [{"id": "example-bank", "label": "Example bank", "ownership": "personal", "balancePence": -1200, "asOf": "2026-09-21"}], "months": [{"month": "2026-08", "incomePence": 500000, "outflowPence": 450000, "netPence": 50000, "salaryPence": 400000, "categories": [{"label": "Refund", "amountPence": -100}]}], "budget": {"incomePence": 400000, "incomeBasis": "Synthetic salary", "essentials": [{"label": "Housing", "amountPence": 150000, "note": "Full share"}], "workCostsPence": 20000, "workCostsNote": "Dated average", "scenarios": [{"label": "Planned change", "status": "planned", "monthlyAdjustmentPence": -10000, "note": "Unconfirmed"}]}, "opportunities": [{"label": "Shopping", "monthlyPence": 60000, "note": "Review actual purchases", "suggestedCapPence": 40000}], "loans": [{"id": "example-loan", "lender": "Example lender", "purpose": "House repairs", "status": "active", "monthlyPaymentPence": 20000, "balancePence": 700000, "balanceAsOf": "2026-09-21", "balanceKind": "statement", "settlementPence": 650000, "settlementAsOf": "2026-09-21", "paymentsRemaining": 35, "originalPrincipalPence": 1000000, "nextPaymentDate": "2026-10-01", "rateNote": "Verify terms", "notes": "Synthetic loan", "sourceIds": ["source"]}], "notes": ["Dated synthetic review"], "sources": [{"id": "source", "label": "Example statement", "url": "https://example.com/statement", "asOf": "2026-09-21"}]}',true);
select ok((select relrowsecurity from pg_class where oid='public.helm_finance_oauth_clients'::regclass),'Finance approvals use RLS');
select ok((select relrowsecurity from pg_class where oid='public.helm_finance_mutation_receipts'::regclass),'Finance receipts use RLS');
select ok(not has_table_privilege('authenticated','public.helm_finance_oauth_clients','select'),'approval table private');
select ok(not has_table_privilege('authenticated','public.helm_finance_mutation_receipts','select'),'receipt table private');
select ok(not has_function_privilege('anon','public.finance_get_review()','execute'),'anonymous read denied');
select ok(not has_function_privilege('authenticated','helm_private.validate_finance_payload(jsonb,text)','execute'),'private validator denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f3111111-1111-4111-8111-111111111111","role":"authenticated","is_anonymous":false}',true);
select is(public.finance_get_review(),null::jsonb,'new account has no review');
select lives_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000001',current_setting('finance.test.draft')::jsonb,null)$$,'browser saves a valid review');
select set_config('finance.test.original',public.finance_get_review()::text,true);
select is(public.finance_get_review()->>'id','current','review has server assigned singleton id');
select is((public.finance_get_review()->'accounts'->0->>'balancePence')::integer,-1200,'signed bank balances persist');
select is((public.finance_get_review()->'loans'->0->>'balancePence')::integer,700000,'loan account balance persists');
select is((public.finance_get_review()->'loans'->0->>'settlementPence')::integer,650000,'settlement remains separate');
select lives_ok($$select public.approve_inventory_oauth_client('other-domain-client','Other agent')$$,'Inventory approval independent');
select lives_ok($$select public.approve_employment_oauth_client('other-domain-client','Other agent')$$,'Employment approval independent');
select lives_ok($$select public.approve_equity_oauth_client('other-domain-client','Other agent')$$,'Equity approval independent');
select set_config('request.jwt.claims','{"sub":"f3111111-1111-4111-8111-111111111111","role":"authenticated","client_id":"other-domain-client"}',true);
select throws_ok($$select public.finance_get_review()$$,'42501','This OAuth client is not approved for Sabah One Finance.','other approvals do not grant Finance');
select throws_ok($$select public.approve_finance_oauth_client('other-domain-client','Self')$$,'42501','OAuth clients cannot use this Sabah One interface.','OAuth cannot self approve');
select set_config('request.jwt.claims','{"sub":"f3111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select lives_ok($$select public.approve_finance_oauth_client('finance-client','Finance agent')$$,'browser grants Finance');
select is(jsonb_array_length(public.list_finance_oauth_clients()),1,'own approvals listed');
select set_config('request.jwt.claims','{"sub":"f3111111-1111-4111-8111-111111111111","role":"authenticated","client_id":"finance-client"}',true);
select is(public.finance_get_review(),current_setting('finance.test.original')::jsonb,'approved agent reads own review');
select throws_ok($$select public.equity_list_positions()$$,'42501','This OAuth client is not approved for Sabah One Equity.','Finance does not authorize Equity');
select throws_ok($$select public.inventory_search()$$,'42501','This OAuth client is not approved for Sabah One Inventory.','Finance does not authorize Inventory');
select throws_ok($$select public.employment_list_applications()$$,'42501','This OAuth client is not approved for Sabah One Employment.','Finance does not authorize Employment');
select throws_ok($$select public.get_helm_account_snapshot()$$,'42501','This session cannot read a Sabah One account snapshot.','agent cannot read account snapshot');
select throws_ok($$select public.apply_helm_mutations('f3000000-0000-4000-8000-000000000099','[]')$$,'42501','OAuth clients cannot use this Sabah One interface.','agent cannot use generic writes');
select is((select count(*) from public.helm_records where collection='financeReviews'),0::bigint,'OAuth direct records read denied');
select set_config('finance.test.receipt',public.finance_save_review('f3000000-0000-4000-8000-000000000002',current_setting('finance.test.draft')::jsonb,current_setting('finance.test.original')::jsonb->>'updatedAt')::text,true);
select is(public.finance_save_review('f3000000-0000-4000-8000-000000000002',current_setting('finance.test.draft')::jsonb,current_setting('finance.test.original')::jsonb->>'updatedAt'),current_setting('finance.test.receipt')::jsonb,'exact retry returns original receipt');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000002',current_setting('finance.test.draft')::jsonb||'{"notes":[]}',current_setting('finance.test.original')::jsonb->>'updatedAt')$$,'22023','Finance idempotency key was reused with different arguments or client.','request id cannot change input');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000003',current_setting('finance.test.draft')::jsonb,current_setting('finance.test.original')::jsonb->>'updatedAt')$$,'40001','Finance review changed; reload before saving.','stale write rejected');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000004',current_setting('finance.test.draft')::jsonb,null)$$,'40001','Finance review changed; reload before saving.','null token cannot overwrite review');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000010',current_setting('finance.test.draft')::jsonb||'{"asOf":"2026-02-30"}',public.finance_get_review()->>'updatedAt')$$,'22023','Finance dates must be valid YYYY-MM-DD dates.','invalid draft rejected: 10');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000011',current_setting('finance.test.draft')::jsonb||'{"asOf":"0000-01-01"}',public.finance_get_review()->>'updatedAt')$$,'22023','Finance dates must be valid YYYY-MM-DD dates.','invalid draft rejected: 11');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000012',current_setting('finance.test.draft')::jsonb||'{"userId":"other"}',public.finance_get_review()->>'updatedAt')$$,'22023','Unsupported Finance field: userId.','invalid draft rejected: 12');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000013',current_setting('finance.test.draft')::jsonb||'{"id":"other"}',public.finance_get_review()->>'updatedAt')$$,'22023','Finance identity and timestamps are assigned by the server.','invalid draft rejected: 13');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000014',jsonb_set(current_setting('finance.test.draft')::jsonb,'{months,0,netPence}','1'),public.finance_get_review()->>'updatedAt')$$,'22023','Finance monthly net must equal income minus outflow.','invalid draft rejected: 14');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000015',jsonb_set(current_setting('finance.test.draft')::jsonb,'{budget,incomePence}','1.5'),public.finance_get_review()->>'updatedAt')$$,'22023','Finance incomePence must be a bounded number.','invalid draft rejected: 15');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000016',jsonb_set(current_setting('finance.test.draft')::jsonb,'{loans,0,balancePence}','-1'),public.finance_get_review()->>'updatedAt')$$,'22023','Finance balancePence must be a bounded number.','invalid draft rejected: 16');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000017',current_setting('finance.test.draft')::jsonb#-'{loans,0,settlementAsOf}',public.finance_get_review()->>'updatedAt')$$,'22023','Finance loan balances and settlements require their own dates.','invalid draft rejected: 17');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000018',jsonb_set(current_setting('finance.test.draft')::jsonb,'{sources,0,url}','"https://user:password@example.com"'),public.finance_get_review()->>'updatedAt')$$,'22023','Finance sources require HTTP or HTTPS URLs without credentials.','invalid draft rejected: 18');
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000019',jsonb_set(current_setting('finance.test.draft')::jsonb,'{loans,0,sourceIds}','["missing"]'),public.finance_get_review()->>'updatedAt')$$,'22023','Finance loans reference an unknown source.','invalid draft rejected: 19');

select set_config('request.jwt.claims','{"sub":"f3222222-2222-4222-8222-222222222222","role":"authenticated","client_id":"finance-client"}',true);
select throws_ok($$select public.finance_get_review()$$,'42501','This OAuth client is not approved for Sabah One Finance.','approval does not cross accounts');
select set_config('request.jwt.claims','{"sub":"f3222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select lives_ok($$select public.approve_finance_oauth_client('finance-client','Second account')$$,'second account independently approves same client');
select set_config('request.jwt.claims','{"sub":"f3222222-2222-4222-8222-222222222222","role":"authenticated","client_id":"finance-client"}',true);
select is(public.finance_get_review(),null::jsonb,'same client cannot read other account');
select lives_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000001',current_setting('finance.test.draft')::jsonb||'{"notes":["Second account"]}',null)$$,'same request id scoped by account');
select set_config('request.jwt.claims','{"sub":"f3111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select is(public.finance_get_review()->'notes','["Dated synthetic review"]'::jsonb,'other account save cannot alter first account');
select is((select count(*) from public.helm_records where collection='financeReviews'),1::bigint,'browser reload sees one owned review');
select lives_ok($$select public.revoke_finance_oauth_client('finance-client')$$,'browser revokes Finance');
select set_config('request.jwt.claims','{"sub":"f3111111-1111-4111-8111-111111111111","role":"authenticated","client_id":"finance-client"}',true);
select throws_ok($$select public.finance_save_review('f3000000-0000-4000-8000-000000000002',current_setting('finance.test.draft')::jsonb,current_setting('finance.test.original')::jsonb->>'updatedAt')$$,'42501','This OAuth client is not approved for Sabah One Finance.','revocation denies exact replay');
select set_config('request.jwt.claims','{"sub":"f3111111-1111-4111-8111-111111111111","role":"authenticated","is_anonymous":true}',true);
select throws_ok($$select public.finance_get_review()$$,'42501','A signed-in Sabah One account is required.','anonymous session denied');
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select public.finance_get_review()$$,'42501','A signed-in Sabah One account is required.','missing identity denied');
select * from finish();
rollback;
